insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/jp/10299', E'ja', 31, E'鳥取砂丘', E'鳥取砂丘（とっとりさきゅう）は、鳥取県鳥取市の日本海海岸に広がる日本の代表的な海岸砂丘である。4km、東西16kmに広がる。\n\n1955年（昭和30年）に国の天然記念物に、2007年（平成19年）に日本の地質百選に選定された。大山と並んで鳥取県のシンボルの一つとされている。\n\n日本三大砂丘の1つだが、その他の2つについては諸説がある。', E'["https://resources.matcha-jp.com/resize/720x2000/2021/01/08-111552.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110652.webp","https://resources.matcha-jp.com/resize/720x2000/2021/01/08-111553.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110645.webp"]'::jsonb, E'2020-12-18'::timestamptz, E'鳥取砂丘', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E9%B3%A5%E5%8F%96%E7%A0%82%E4%B8%98'),
(E'https://matcha-jp.com/jp/23025', E'ja', 32, E'出雲大社', E'出雲大社（いずもおおやしろ / いずもたいしゃ）は、島根県出雲市大社町杵築東にある神社。祭神は大国主大神。式内社（名神大）、出雲国一宮で旧社格は官幣大社。\n\n神社本庁の別表神社。宗教法人出雲大社教の宗祠。明治維新に伴う近代社格制度下において唯一「大社」を名乗る神社であった。出雲大社の社紋（神紋）は二重亀甲に剣花菱（にじゅうきっこうにけんはなびし）。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213006.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213007.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213008.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213009.webp"]'::jsonb, E'2024-11-29'::timestamptz, E'出雲大社', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%87%BA%E9%9B%B2%E5%A4%A7%E7%A4%BE'),
(E'https://matcha-jp.com/jp/3804', E'ja', 32, E'【島根県】17年連続第1位!!日本一の庭園をもつ「足立美術館」の見どころ', E'島根県安来市にある「足立美術館」は、アメリカの日本庭園専門誌の日本庭園ランキングで17年連続で1位(2020年時点)に選ばれている名実ともに日本を代表する庭園をもつ美術館です。日本画と庭園を鑑賞することで、アートはもちろん、日本の四季や美しい景色をより深く味わえる場所。この記事では、そんな足立美術館の見どころを紹介します。\n\n島根県安来市にある「足立美術館」。広大な敷地をもち、日本画を中心としたコレクションのほか、自然と調和した枯山水庭をはじめとする5万坪の日本庭園が高く評価されている美術館です。\n\nこちらの庭園はアメリカの日本庭園専門誌『The Journal of Japanese Gardening』の日本庭園ランキングで、なんと17年連続で1位(2020年時点)に選ばれ、名実ともに日本を代表する庭園なのです。\n\n同美術館は庭園と近代日本画コレクションがある本館と、現代日本画を展示する新館があります。庭園を鑑賞するには本館へ行きましょう。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15155.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15151.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15161.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15162.webp"]'::jsonb, E'2018-12-06'::timestamptz, E'足立美術館', null, null),
(E'https://matcha-jp.com/jp/17526', E'ja', 31, E'島根・鳥取を2泊3日でサイクリング！温泉、グルメ、絶景を堪能しよう', E'島根・鳥取県は、多くの温泉や地元グルメ、自然の絶景が楽しめる場所です。さらに島根県には縁結びのパワースポット ・出雲大社が、鳥取県にはたくさんの妖怪ブロンズ像がある「水木しげるロード」もあります。今回は両県を巡る2泊3日の自転車旅を紹介します。\n\n今回は島根、鳥取を横断して2県を2泊3日自転車で巡る旅をご紹介します。心身を癒す温泉に地元のグルメ、最高の景色が楽しめます。自転車好きには見逃せない、2県の魅力を体験します！\n\n本記事で紹介している商品や入館料は取材時のものです。今後、変更となる可能性があるので、ご注意ください。\n\n近年、預け荷物で自転車を持ってくる旅行客が増えています。こうした自転車利用者へのサービス向上のため、「出雲縁結び空港」では1Fの総合案内所で空気入れを無料で貸し出しています。空港に着いた旅行客が自転車を組み立てる時、一層便利ですね！', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157653.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157655.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157638.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157639.webp"]'::jsonb, E'2023-12-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/9475', E'ja', 32, E'大自然に癒やされる！離島・隠岐諸島で過ごす3日間のリトリート', E'日本海に浮かぶ隠岐諸島。フェリーや飛行機でしか行けませんが、世界でも有数の稀少で美しい景観と、見渡す限り輝く海を満喫できます。日頃のストレスから解放され、隠岐と島前の島々でゆっくりとした生活に浸りましょう。\n\n島根県沖にある日本の隠岐諸島は、世界でもっとも豊かな自然がある観光地の1つです。中でも、島前(どうぜん)は、特に訪れて欲しい場所。岩場の多い地形にクリスタルブルーの海、美しい夕日、そして魅力的な村があなたを迎えてくれます。\n\n島前にはコンビニはありません。この島には生活において必要最低限な設備しかなく、東京や大都市の騒々しい雰囲気とはまったく違います。このシンプルな考え方と島の魅力、そして美しい自然とが結びつき、現代社会の便利さや快適さから少しだけ、距離をとることができます。\n\nここは、母なる自然によって日常生活のストレスから解放される場所。できることなら、島の魅力を存分に味わうためには3日以上の滞在がオススメ。この記事では、隠岐で自然を満喫する3日間のプラン、アクセス情報を紹介します。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/03/03-98704.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/03-98751.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/03-98680.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/03-98682.webp"]'::jsonb, E'2020-03-06'::timestamptz, E'隠岐諸島', null, null),
(E'https://matcha-jp.com/jp/3825', E'ja', 33, E'岡山のおみやげはここで買おう！オススメのおみやげスポット4選', E'岡山県には、桃やブドウなどのブランドフルーツのほか、きびだんごなどおいしいものがたくさん。本記事では、遠方からお越しの方でも安心して購入できる賞味期限の長いおみやげと、岡山駅などからのアクセスが便利なおみやげスポット4カ所を紹介します。\n\n中国地方に位置する岡山県には、昔ながらの美しい街並みが残る倉敷や日本三名園のひとつ「岡山後楽園」など魅力的な観光スポットがあります。\n\nそんな岡山のおみやげとして有名なのが、日本の有名なおとぎ話『桃太郎』に登場する、こちらの写真の「きびだんご(※1)」。また、瀬戸内海に面した温暖な気候を生かしてつくられた白桃やブドウなどのブランドフルーツ、瀬戸内海でとれた新鮮な魚介類もおみやげとして人気があります。\n\nでも、海外など遠いところから訪れる場合は、賞味期限が気になりますよね。ご安心ください。岡山には、地元のおいしい水と米を使って作られた日本酒や、地元産のフルーツをそのまま缶詰にしたフルーツ缶など、比較的賞味期限が長いおみやげもたくさんあります。また、世界20カ国以上で愛される「桃太郎デニム」や「備前焼」の器も岡山の名産品。食以外のおみやげも豊富なんです。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/17-13944.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13413.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13415.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13412.webp"]'::jsonb, E'2017-02-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/23405', E'ja', 33, E'岡山城', E'岡山城（おかやまじょう）は、徳島県阿南市新野町入田にある城跡。現在は室比賣神社（室姫神社）の境内となっており、地域により維持管理されている。\n\n「岡山城址公園」として小さい公園が整備されており、隣接する日亜化学工業新野工場や新野町の市街が見渡せる。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216696.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216685.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216686.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216687.webp"]'::jsonb, E'2024-12-23'::timestamptz, E'岡山城', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%B2%A1%E5%B1%B1%E5%9F%8E_(%E9%98%BF%E6%B3%A2%E5%9B%BD)'),
(E'https://matcha-jp.com/jp/23896', E'ja', 33, E'【2025】岡山のデートスポット12選！のんびりできるスポットや穴場を紹介', E'岡山には、自然や歴史、アートを楽しめるデートスポットが多く揃っています。本記事では、のんびり過ごせる穴場や、雨の日でも快適に楽しめる場所など、2人だけの特別な時間を過ごせるデートスポットをまとめました。\n\n岡山のデートスポットは、趣のある街並みと瀬戸内海の温暖な気候が育む豊かな自然が魅力です。風情ある街並みを散策しながらレトロな雰囲気を楽しんだり、四季折々の自然の中でのんびり過ごせます。\n\n都会の喧騒を離れ、穏やかな景色の中でリラックスしながら、2人だけの特別なひとときを楽しんでみてはいかがでしょうか。\n\n岡山には、歴史の趣を感じながら過ごせるデートスポットが点在しています。風情ある庭園や城跡、昔ながらの町並みを歩けば、時代を超えたロマンを感じられるはず。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/03-222254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/05-222659.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/03-222256.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/03-222257.webp"]'::jsonb, E'2025-02-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/5124', E'ja', 34, E'帝釈峡', E'帝釈峡（たいしゃくきょう）は、中国山地に位置する広島県北東部の庄原市及び神石郡神石高原町にまたがる、全長18キロメートルの峡谷。\n\n国の名勝（1923年）に指定されており、比婆道後帝釈国定公園の主要景勝地。高梁川水系成羽川（東城川）支川の帝釈川（たいしゃくがわ）の一部。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246201.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/29-128722.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/2615.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58360.webp"]'::jsonb, E'2018-07-25'::timestamptz, E'帝釈峡', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%B8%9D%E9%87%88%E5%B3%A1'),
(E'https://matcha-jp.com/jp/11239', E'ja', 34, E'厳島神社', E'厳島神社（いつくしまじんじゃ、公式表記:嚴島神社）は、広島県廿日市市の厳島（宮島）にある神社。式内社（名神大社）、安芸国一宮。\n\n旧社格は官幣中社で、現在は神社本庁の別表神社。神紋は「三つ盛り二重亀甲に剣花菱」。古くは「伊都岐島神社」とも記された。全国に約500社ある厳島神社の総本社である。\n\n佐伯直の直系が代々世襲して来たとされているが、一時期藤原氏に横取りされた時期があったものの政略結婚により取り戻し、古代から現在も続いていると記載されている。\n\n広島湾に浮かぶ厳島（宮島）の北東部、弥山（標高535メートル）北麓に鎮座する。厳島は一般に「安芸の宮島」とも呼ばれ日本三景のひとつに数えられている。平家から信仰され、平清盛により現在の海上に立つ大規模な社殿が整えられた。社殿は現在、本殿・拝殿・回廊など6棟が国宝に、14棟が重要文化財に指定されている。そのほか、平家の納めた平家納経をはじめとした国宝・重要文化財の工芸品を多数納めている。厳島神社の平舞台（国宝：附指定）は日本三舞台の1つに数えられるほか、海上に立つ高さ16メートルの大鳥居（重要文化財）は日本三大鳥居のひとつである。また、夏に行われる例祭は「管絃祭」と呼ばれている。1996年（平成8年）12月にユネスコの世界文化遺産に「厳島神社」として登録されている。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127864.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127865.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127866.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127867.webp"]'::jsonb, E'2022-06-17'::timestamptz, E'厳島神社', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%8E%B3%E5%B3%B6%E7%A5%9E%E7%A4%BE'),
(E'https://matcha-jp.com/jp/3219', E'ja', 34, E'厳島神社', E'厳島神社（いつくしまじんじゃ、公式表記:嚴島神社）は、広島県廿日市市の厳島（宮島）にある神社。式内社（名神大社）、安芸国一宮。\n\n旧社格は官幣中社で、現在は神社本庁の別表神社。神紋は「三つ盛り二重亀甲に剣花菱」。古くは「伊都岐島神社」とも記された。全国に約500社ある厳島神社の総本社である。\n\n佐伯直の直系が代々世襲して来たとされているが、一時期藤原氏に横取りされた時期があったものの政略結婚により取り戻し、古代から現在も続いていると記載されている。\n\n広島湾に浮かぶ厳島（宮島）の北東部、弥山（標高535メートル）北麓に鎮座する。厳島は一般に「安芸の宮島」とも呼ばれ日本三景のひとつに数えられている。平家から信仰され、平清盛により現在の海上に立つ大規模な社殿が整えられた。社殿は現在、本殿・拝殿・回廊など6棟が国宝に、14棟が重要文化財に指定されている。そのほか、平家の納めた平家納経をはじめとした国宝・重要文化財の工芸品を多数納めている。厳島神社の平舞台（国宝：附指定）は日本三舞台の1つに数えられるほか、海上に立つ高さ16メートルの大鳥居（重要文化財）は日本三大鳥居のひとつである。また、夏に行われる例祭は「管絃祭」と呼ばれている。1996年（平成8年）12月にユネスコの世界文化遺産に「厳島神社」として登録されている。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/10/31-131151.webp","https://resources.matcha-jp.com/resize/720x2000/2022/10/31-131152.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/DSC01521.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/hirosima3_20160823h.webp"]'::jsonb, E'2017-01-05'::timestamptz, E'厳島神社', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%8E%B3%E5%B3%B6%E7%A5%9E%E7%A4%BE'),
(E'https://matcha-jp.com/jp/23396', E'ja', 35, E'山口観光モデルコース1泊2日！温泉とグルメを満喫＋半日・2泊3日プランも', E'歴史や自然、温泉を存分に満喫できる山口県の魅力的な観光旅行。錦帯橋や秋芳洞などの名所巡りに加え、湯田温泉で心身を癒す1泊2日・2泊3日モデルコースや、幕末の雰囲気を堪能する半日コースなど、さまざまなドライブプランを紹介しています。これらのコースを活用すれば、山口県の多彩な魅力を余すところなく楽しめます。\n\n山口県には歴史と自然を感じられる「岩国エリア」や幕末の歴史スポットを巡れる「荻エリア」、海岸景観が楽しめる「下関・宇部エリア」、高原・湖沼から雄大な自然を満喫できる「秋吉エリア」などの観光スポットがあります。これらの観光地を回るには、1泊2日以上で計画を立てるのがおすすめです。\n\nこの記事では、山口の定番名所をめぐる3つのモデルコースを紹介します。山口県の豊かな自然や美味しい食べ物を楽しんで、旅を満喫しましょう。\n\n歴史と自然を楽しむ1泊2日の山口ドライブコース。錦帯橋や岩国城を訪れ、和牛弁天で美味しい昼食を楽しみましょう。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216574.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216575.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216576.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216577.webp"]'::jsonb, E'2024-12-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/17332', E'ja', 33, E'【山口・広島・岡山】2泊3日自転車の旅！絶景、歴史スポット、地元グルメを堪能', E'山口県は壮観なカルスト台地などの自然景観で有名です。広島県には懐かしい空気に満ちた街があり、岡山県のジーンズストリートは独自の風格を醸し出しています。今回は3県を横断する2泊3日の自転車の旅をご紹介します。道中、美しい景色を眺め、歴史探訪をし、そして地元グルメも楽しめます！\n\n今回は本州の西に位置する山口・広島・岡山の3県を横断する2泊3日の自転車の旅をご紹介します。旅の途中では、絶景、歴史探訪、そして地元のグルメを思いっきり楽しめます。自転車の好きな人にとっては、見逃せない思い出深い経験になること間違いなしです！\n\n本記事で紹介している商品や入館料は取材時のものです。今後、変更となる可能性があるので、ご注意ください。\n\n湯田温泉は白狐が発見した温泉と言われ、毎日2,000トンの豊富な湧出量に恵まれています。泉質はアルカリ性で保湿効果があり、美肌の湯と言われています。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155286.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155288.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155292.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155294.webp"]'::jsonb, E'2023-12-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/1603', E'ja', 35, E'【絶景】日本一賽銭を入れづらい神社、山口「元乃隅神社」', E'山口県の元乃隅神社は、日本で一番賽銭を入れづらいことで有名です。2015年には、米国CNNにて「日本の美しい風景31選」にも選ばれて、世界が認める絶景としても注目を浴びる元乃隅神社を紹介します。\n\n日本の神社では、賽銭(さいせん)を入れて願い事をするのが定番です。普通は小銭を専用の箱に放り込むだけでいいのですが、中には賽銭を入れるだけでひと苦労の神社があるのです。\n\n今回は、賽銭を入れることができれば願いが叶うと言われている「元乃隅神社(もとのすみじんじゃ、旧称・元乃隅稲成神社)」を、世界も認める絶景とともに紹介します。 あわせて読みたい いまさら聞けない 神社の正しい参拝方法\n\n神社ができたきっかけは1955年にさかのぼります。地域の漁師の夢に白いキツネが現れ、「自分を祀る神社を建てよ」とお告げを与えたことが契機になったそうです。', E'["https://resources.matcha-jp.com/old_thumbnails/200x2000/874.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123262.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123263.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123264.webp"]'::jsonb, E'2018-03-21'::timestamptz, E'元乃隅神社', null, null),
(E'https://matcha-jp.com/jp/1851', E'ja', 35, E'【山口県】日本3大名塔のひとつ、品格ただよう「瑠璃光寺五重塔」', E'日本三大名塔と言われている。山口県の瑠璃光寺五重塔をご紹介します。室町時代の最もすぐれた建築として評価の高い瑠璃光寺五重塔は、とても美しく息を飲むほどです。\n\n寺院の境内に立つ五重塔は日本人のみならず多くの訪日旅行者の心を掴む美しい建築物です。 そんな日本の五重塔の中でも特に見事な、「日本3大名塔」と呼ばれる塔があることをご存知でしょうか。それが、京都の醍醐寺(だいごじ)、奈良の法隆寺、そして山口の瑠璃光寺にある3つの五重塔です。\n\n今回はそれらの中から、山々や池に囲まれた姿が印象的な瑠璃光寺五重塔をご紹介します。\n\n瑠璃光寺五重塔は、1442年に建立されました。室町時代(※1)中期における優れた建築のひとつで、当時山口を中心に花開いた大内(おおうち)文化の最高傑作とも評されています。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/18-126679.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/18-126680.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/18-126681.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/18-126682.webp"]'::jsonb, E'2016-05-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/23132', E'ja', 36, E'徳島のおしゃれカフェ7選！夜営業・インスタ映えスポットも紹介', E'豊かな自然に囲まれる徳島。そんな徳島にはおしゃれなカフェが数多くあります。この記事では、徳島のおしゃれで人気なカフェを7つご紹介します。夜まで開いている店やインスタ映えする魅力的な店まで広くご紹介するので、ぜひ参考にしてみてくださいね。\n\nそんな徳島ですが、山だけではなく海にも近いため、山海の恵みを生かした地元食材を使った料理を提供するカフェが多くあります。\n\n広々とした店内で、開放的なひとときを過ごせるカフェも多く、コーヒーや食事はもちろん、空間的にも高い満足度が得られます。\n\nこの記事では、徳島で人気のあるおしゃれなカフェを7つご紹介します。夜遅くまで開いている店とインスタ映えする店に分けて紹介するので、ぜひご自分にぴったりなカフェを見つけてくださいね。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/08-213997.webp"]'::jsonb, E'2024-12-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/24194', E'ja', 36, E'徳島観光のモデルコース！日帰りや1泊2日で回れるコースを紹介', E'四国の東端に位置する徳島県。徳島といえば渦潮ですが、それ以外にどこに行けばいいか迷う人も多いでしょう。そこで本記事では、日帰りや1泊2日で徳島観光できるモデルコースをご紹介します。各スポットの特徴もお伝えするので、参考にしてくださいね。\n\n徳島県は四国地方の東端に位置する県。最も有名な観光スポットは渦潮ですが、それ以外はあまり知らないという人もいるのでは？\n\nたとえば、夏の徳島では「阿波おどり」が開催され、グルメではなると金時などの豊かな作物に恵まれています。\n\nまた、県内は山地が多く、面積の内約8割を山地が占めています。雄大な自然に囲まれているのも徳島の大きな特徴ですね。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225224.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225225.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225226.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225227.webp"]'::jsonb, E'2025-02-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/12008', E'ja', 36, E'【2023】徳島の観光スポット12選！グルメやイベント情報も', E'四国にある徳島県は、伝統文化と豊かな自然の魅力が溢れる観光地です。本記事では、徳島の観光スポット12選をご紹介します。定番スポットはもちろん、注目の最新スポット、徳島ならではのご当地グルメや阿波踊りなどのイベント情報もあるので、ぜひチェックしてみてくださいね！\n\n徳島県は、4つの県(徳島、香川、愛媛、高知)からなる四国地方にある県の1つです。\n\n伝統文化や豊かな自然があふれる徳島県には、約400年にわたり伝承されてきた大迫力の伝統芸能「阿波踊り」や、植物を編んで作られた日本三代奇橋の1つ「祖谷のかずら橋」など、ここにしかない見どころがたくさんあります。\n\nそこで本記事では、徳島県のオススメ観光スポットをご紹介します。近年注目を集めている最新スポットはもちろん、徳島グルメ、イベント、徳島へのアクセス方法など幅広くお届けするので、ぜひ最後までチェックしてみてください！', E'["https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138208.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138207.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138209.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138211.webp"]'::jsonb, E'2023-05-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/3946', E'ja', 37, E'小豆島', E'小豆島（しょうどしま）は、瀬戸内海・播磨灘にある島。行政区分は香川県小豆郡に属し、小豆島町、土庄町の2町からなり、人口は2万5881人（2020年度推計）。\n\n近年、人口が減少の一途をたどっており、2013年6月24日に隣接する沖之島とあわせて、国土交通省より「離島振興法」の指定を受けた。\n\n古代には「あずきしま」と呼ばれ、その後、中世までは「しょうずしま」と呼ばれた。素麺、醤油、佃煮、胡麻油、オリーブなどの生産が盛んであり、いずれも日本有数の生産地となっている。\n\n特にオリーブは国内栽培の発祥地として広く知られる。小説『二十四の瞳』の作者壺井栄の故郷としても知られ、小豆島をロケ地として、同小説はこれまで2回映画化された。また、近年では漫画/アニメーション「からかい上手の高木さん」の聖地（特に、土庄町）としても知られている。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135895.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135891.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135892.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/16-138236.webp"]'::jsonb, E'2018-02-22'::timestamptz, E'小豆島', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%B0%8F%E8%B1%86%E5%B3%B6'),
(E'https://matcha-jp.com/jp/7360', E'ja', 37, E'【香川】父母ヶ浜の5つの楽しみ方！日本最高の夕日スポットでグルメも体験も楽しもう', E'香川県にある父母ヶ浜は、日本最高級の夕日が楽しめる絶景スポットです。本記事では、絶景の取り方や、地元グルメが楽しめるカフェ、おみやげ店、街歩きスポット、地元の魅力が感じられる宿など、父母ヶ浜の楽しみ方を5つ紹介します！\n\nPicture coutesy of 三豊市 香川県西部の三豊(みとよ)市にある父母ヶ浜(ちちぶがはま)は、2016年以降、SNSを通して人気となった絶景スポット。\n\n特に夕方、美しい景観が見られることから、日本の大手旅行誌で2018年に「行ってみたい夕日絶景ランキング」第1位に選ばれました。\n\nこの絶景の秘密は、干潮時に砂浜にできる潮だまりにあります。風が弱い日は、潮だまりの水が鏡のようになり、空を美しく映し出します。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76985.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76989.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76986.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76987.webp"]'::jsonb, E'2019-04-23'::timestamptz, E'父母ヶ浜', null, null),
(E'https://matcha-jp.com/jp/6312', E'ja', 37, E'ことでんで女子力アップ旅！高松のデザート、雑貨店10選', E'女子旅にぴったりの街、香川県高松市。今回は地元鉄道「ことでん」に乗って、高松市内のスイーツ店や雑貨店を巡りました。老舗や人気店など目白押し。高松を旅するなら見逃せない女子旅の手引きです。\n\n香川県高松市は、女子旅にピッタリの街。そう聞いて意外に感じる方もいるかもしれません。\n\n今回は地元鉄道「高松琴平電気鉄道(通称：ことでん)」に乗って、高松市内のスイーツ店や雑貨店を巡りました。老舗や人気店など目白押し! 意外と知られていない、高松のおしゃれでかわいい一面をご紹介します。\n\nことでん「瓦町駅」を出ると、駅前ロータリーの向かい側にスイーツ店「三びきの子ぶた」があります。可愛い子ぶたが描かれたこのお店は、高松の方なら誰しも懐かしい思い出を持つ、昔ながらのスイーツ屋さんです。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58356.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58354.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58350.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58327.webp"]'::jsonb, E'2018-07-31'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/10574', E'ja', 38, E'映画の舞台になったあの駅も！四国のオススメ鉄道写真スポット3選', E'瀬戸内海と太平洋に囲まれ、中央に山脈が走る四国。日本の原風景が多く残るこの島には、海、山、川を背景に絶景の鉄道写真が撮れるスポットが多数あります。今回は、JR下灘駅をはじめ、徳島県と愛媛県で鉄道写真好き必見の3スポットを紹介します！\n\n瀬戸内海と太平洋に挟まれ、中央に四国山地が走る四国には、海、山、川が織りなす多彩な絶景があります。そんな四国には、ユニークな鉄道写真が撮れるスポットもたくさん！\n\n本記事では、四国に住む筆者が、愛媛県、徳島県で絶景の鉄道写真が撮れる3スポットを紹介します。\n\n今回ご紹介するのはすべてJR四国の路線です。これらの路線では、アンパンマン列車、観光列車「伊予灘ものがたり」「四国まんなか千年ものがたり」など色鮮やかなラッピング列車が走っており、目を楽しませてくれますよ！', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123702.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123703.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123704.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123705.webp"]'::jsonb, E'2021-06-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/22861', E'ja', 38, E'四国観光モデルコース(2泊3日・1泊2日・半日)！絶景やグルメも', E'四国観光のモデルコースを、2泊3日・1泊2日・半日の3パターン紹介しています。広大な四国を、見どころを押さえながら効率的に回れるように考えたプランばかりです。四国の自然を満喫できるスポットや、歴史や文化に触れられるスポットなど、おすすめの観光地を集めています。\n\n豊かな自然が残る四国は、絶景スポットやご当地グルメ、独自の歴史・文化など、魅力がいっぱい。そんな四国を観光するときに参考になるモデルコースを、2泊3日・1泊2日・半日の3パターン紹介します。\n\n車での移動時間、車なしでの移動時間の目安も記載しているので、レンタカーなどでの移動の際に参考にしてください。\n\n▼雄大な自然を楽しむ！四国観光のモデルコースを紹介 ▼【2泊3日】高知〜愛媛！車で巡る王道スポット満喫コース', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211535.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211536.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211537.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211538.webp"]'::jsonb, E'2024-11-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/22343', E'ja', 38, E'道後温泉', E'道後温泉（どうごおんせん）は、四国・愛媛県松山市（旧国伊予国）に湧出する温泉。有馬温泉や白浜温泉と並ぶ日本三古湯の一つである。\n\nその存在は古代から知られ、万葉集巻一にも見える。なおかつてはこの周辺が温泉郡（おんせんぐん）（湯郡）と呼ばれていたが、これはこの温泉にちなむ地名である。\n\n夏目漱石の小説『坊つちやん』（1905年）にも描かれ、愛媛県の代表的な観光地となっている。2007年8月に地域団体商標（地域ブランド）として認定された（申請者は道後温泉旅館協同組合、登録商標第5071495号）。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205443.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205895.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205445.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205447.webp"]'::jsonb, E'2024-10-28'::timestamptz, E'道後温泉', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E9%81%93%E5%BE%8C%E6%B8%A9%E6%B3%89'),
(E'https://matcha-jp.com/jp/23675', E'ja', 39, E'足摺岬', E'足摺岬（あしずりみさき）は、高知県南西部土佐清水市に属し、太平洋（フィリピン海）に突き出る足摺半島の先端の岬。土佐湾の西端であり、足摺宇和海国立公園に指定されている。\n\n古くは嵯陀岬とも称された。また元々は「足摺崎（あしずりざき）」が正式名称であったが、観光地化の進展に伴って改称の議論が起き、昭和40年（1965年）の土佐清水市議会において、広く通称として呼ばれていた「足摺岬（あしずりみさき）」が正式呼称となった。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220269.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220252.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220255.webp"]'::jsonb, E'2025-01-17'::timestamptz, E'足摺岬', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E8%B6%B3%E6%91%BA%E5%B2%AC'),
(E'https://matcha-jp.com/jp/23234', E'ja', 39, E'高知のおすすめグルメ5選！鍋焼きラーメン・カツオなどランキングで紹介！', E'高知県に行ったらぜひ味わいたい、おすすめのグルメをランキング形式で紹介した記事です。海や川の恵みが豊かな高知県では、カツオや四万十うなぎ、クエなどの名物料理を味わえます。鍋焼きラーメンや地鶏の土佐ジローも有名なので、おすすめの店舗をしっかりチェックしておきましょう。\n\n高知に旅行に行ったら、ご当地グルメを味わうのも旅の楽しみのひとつです。高知には海の幸をはじめとして、地元の特産品を使った名物料理が数多くあります。\n\n高知旅行のプランを立てるのであれば、ぜひ本記事を参考にしてグルメの計画も立てておきましょう。\n\n▼高知に行ったら絶対に食べたい名物・B級グルメをご紹介！ ▼大地の恵みや海の恵み！高知のおすすめグルメとは？ ▼1位.カツオのタタキ', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/18-215773.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215243.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215244.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/18-215774.webp"]'::jsonb, E'2024-12-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/7851', E'ja', 39, E'高知でしたい10のこと(絶景・歴史スポット・グルメなどまとめ)', E'四国地方の高知県は、歴史や美しい自然、おいしいグルメが味わえる場所。高知が誇る景勝地、桂浜、仁淀川や、偉人・坂本龍馬にまつわるスポット、おいしいカツオがいただける市場、ゆずの名産地などを紹介します。\n\n四国地方にある高知県は、美しい自然とおいしいグルメで知られます。美しい青色が"仁淀ブルー"とも称される仁淀川、周辺の松の緑と紺碧の海とのコントラストが目を引く桂浜といった景勝地はぜひ訪れたいもの。\n\nグルメでは、赤身で旨味の強い魚・カツオや、爽やかな香りの柑橘類・ゆずが有名です。カツオの刺身の表面を軽く炙った料理「カツオのタタキ」は必食です。\n\n日本でもっとも有名な侍のひとり、坂本龍馬の出身地であることから龍馬ゆかりの史跡も多数あります。高知で経験したい10のことを紹介します。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85065.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101271.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/10-101196.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/10-101197.webp"]'::jsonb, E'2019-09-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/6301', E'ja', 40, E'5000杯食べたマニアがオススメ！福岡県・博多周辺の激ウマ人気ラーメン8選', E'通算5000杯以上のラーメンを食べた筆者が、福岡県・博多のオススメラーメンを厳選してご紹介します。この記事では、博多名物の豚骨ラーメンをはじめ、博多でも増えている豚骨以外のラーメンも紹介しています。博多のラーメン情報なら、MATCHAを見れば間違いない。\n\n福岡県・博多と聞くと、白濁したスープの豚骨ラーメンを思い浮かべる人は多いのではないでしょうか。\n\nもちろん、博多ではまだまだ豚骨ラーメンが多いのですが、最近ではそれ以外のラーメンも見かけるようになりました。この記事では豚骨ラーメンに加えて、博多で最近増えている豚骨以外のラーメンも紹介しています。\n\n博多と言えば、やはり豚骨ラーメンが有名。その中でも特に人気が高いのが、この「博多一双 博多駅東本店」です。ラーメンは豚骨ラーメン1種類のみで、あとはトッピングとサイドメニューだけというシンプルなメニュー構成(写真の「ラーメン」は、税込650円)。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/09-58093.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58103.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58104.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58105.webp"]'::jsonb, E'2018-07-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/1354', E'ja', 40, E'舞鶴公園', E'舞鶴公園（まいづるこうえん）は、福岡県福岡市中央区にある福岡城の本丸址を中心とする公園（総合公園）。公園を含む現行の行政地名は、城内（じょうない、（ローマ字表記: Jōnai）である。\n\n福岡市中心部大濠公園の東部に隣接する位置にあり、市民の憩いの場となっている。城址には約500本の桜が植えられており、福岡城さくらまつりが開催される毎年春には大勢の花見客で賑わう。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246201.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58455.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58458.webp"]'::jsonb, E'2018-11-15'::timestamptz, E'舞鶴公園', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E8%88%9E%E9%B6%B4%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/jp/2624', E'ja', 40, E'福岡市・博多でオススメの観光スポット11選＆グルメ', E'九州で最大の都市・福岡市(博多)は、ラーメンやもつ鍋といったグルメから、ショッピングスポット、観光スポット、エンターテインメントまで充実した人気の観光地です。本記事では、福岡市(博多)でオススメの観光スポット12選とグルメ4選を紹介します。\n\n福岡県は九州地方で一番大きな県です。その中心都市・福岡市は、九州旅行のハブとも言える大都市です。\n\n那珂川の西側は「福岡」、那珂川の東側は「博多」と呼ばれます。博多ラーメン、もつ鍋といった人気のご当地グルメがあるほか、ショッピングスポットもたくさんあり、「海の中道海浜公園」のように美しい景勝地もあります\n\nさらに近年は、「マリンワールド 海の中道」や「ガンダムパーク福岡」など、エンターテインメントの施設も充実してきました。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/12/30-133403.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/10-122517.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/31-96152.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/28-133386.webp"]'::jsonb, E'2016-12-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/9568', E'ja', 40, E'【2026】福岡のアウトレット・買い物スポット8選！セール情報もあわせて紹介', E'福岡は、おいしいグルメに加え、買い物が楽しめる街です。本記事では、福岡在住の経験がある筆者が、THE OUTLETS KITAKYUSHUをはじめとするアウトレットモールのほか、デパート、ショッピングモールなどのショッピングスポットを紹介します。\n\n九州の玄関口・福岡空港から中心部まで地下鉄で5分で行ける福岡市は、近年、人気が急上昇しています。なぜなら、おいしいグルメに加えて、ショッピングをするにも便利な街だからです！\n\n本記事では、福岡市中心部、そして福岡県内にあるアウトレットモールやショッピングモールを厳選して紹介します。本記事を読めば、福岡での買い物もバッチリ！\n\n福岡県、またその近隣エリアには、THE OUTLETS KITAKYUSHU、鳥栖プレミアム・アウトレットの2つのアウトレットモールと、一部アウトレット店舗が入ったマークイズ福岡ももちがあります。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127833.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127837.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99807.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99808.webp"]'::jsonb, E'2020-03-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/22375', E'ja', 40, E'九州の紅葉の名所＆穴場スポット厳選10選。見ごろとライトアップ情報も', E'この記事では、九州の紅葉スポットをお探しの方に向けて、九州の紅葉の見頃時期と名所・穴場スポット10選をご紹介します。見ごろやライトアップ情報も紹介するので、ぜひ参考にしてみてください！\n\n標高の高いエリアでは、10月中旬から10月下旬にかけて色づき始め、紅葉のピークを迎えます。一方、標高の低いエリアでは、11月中旬から12月上旬頃が見頃になります。\n\n気温や天候によって、紅葉の見頃時期は変わるため、事前に天気情報サイトなどをチェックしておくと良いです。\n\n11月下旬から12月上旬にかけては、黒門周辺のカエデが紅葉し、見事な紅葉の景色が広がります。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206734.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206736.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206737.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/19-141357.webp"]'::jsonb, E'2024-10-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/7306', E'ja', 41, E'絶景撮影スポット、グルメ、アウトレットまで！九州・佐賀でやりたい15のこと', E'九州北部にある佐賀県には、カラフルなバルーンフェスタや美しい棚田などの絶景から、プレミアム・アウトレットなどショッピング、佐賀牛やシーフードを始めとしたグルメまで、ここでしか楽しめないことがたくさん！\n\nカラフルなバルーンフェスタや水中に浮かぶ鳥居、棚田などここでしか見られない絶景。プレミアム・アウトレットやおしゃれな図書館など最新トレンドに触れられるスポット。日本で食べたい新鮮なシーフードに和牛といった絶品ごはん……。\n\nこれらすべてに出会えるのが、九州の佐賀。佐賀でできること、やりたいことをまとめてご紹介しましょう！\n\nまずは、佐賀の場所を把握しておきましょう。佐賀県は九州の北部にあり、東側に九州の玄関口・福岡、西側にはハウステンボスや情緒あふれる街並み知られる長崎があります。 黄色のピンは九州佐賀国際空港', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75929.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75911.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75371.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75372.webp"]'::jsonb, E'2019-04-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/910', E'ja', 41, E'巨大な鯛や龍が街を練り歩く!?「唐津（からつ）くんち」に大熱狂!!【2021年版】', E'「一体これは何なんだ・・・」毎年11月2日から4日の3日間にかけて佐賀県の唐津という場所が熱気に包まれるお祭りがあります。それが「唐津くんち」です。唐津くんちは一度見ると、「また来年も見に来たい！」という方が多く、現在では世界中から約50万人の観光客が訪れるお祭りとなっています。\n\n毎年11月2日から4日の3日間にかけて佐賀県の唐津という場所が熱気に包まれるお祭りがあります。それが「唐津くんち」です。唐津くんちは一度見ると、「また来年も見に来たい！」という方が多く、現在では世界中から約50万人の観光客が訪れるお祭りとなっています。\n\n新型コロナウイルス感染症の現在の状況を踏まえ、規模を縮小して11月3日の「御旅所神幸祭」のみ開催。※11月2日、4日の巡行はありません。 また、主催者である唐津曳山取締会は感染拡大防止のため、沿道での観覧の自粛をお願いしています。\n\n「くんち」とは、穀物などの農作物の豊作に対する感謝の気持ちを込めて、神様を唐津神社から生誕の地までお連れする儀式のことをいいます。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/26-127210.webp","https://resources.matcha-jp.com/archive_files/cn/2015/03/saga_cup_c.webp"]'::jsonb, E'2015-06-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/10410', E'ja', 41, E'お酒好きにオススメ！「鹿島嬉野酒蔵ツアー」で九州が誇る日本酒文化を体験', E'日本の九州地方にある佐賀県鹿島市・嬉野市は、食通にとって体験すべき日本酒と食の文化があります。本記事では、おいしい日本酒とその文化の発見が盛りだくさんの、2日間の酒蔵ツアーを紹介します。\n\n九州地方にある佐賀県鹿島(かしま)市では、代々日本酒造りが盛んに行われてきました。\n\n鹿島の酒蔵の多くは200年以上もの歴史があり、いくつかの酒蔵は観光客にも開かれています。そのため繊細な味をもつ日本酒を知り、楽しむには最適な場所なのです。\n\n2日間にわたる鹿島嬉野酒蔵ツアーでは、江戸時代の町並みを歩き、さまざまなお酒と地域の美食を味わい、さらに酒造りも楽しめます！', E'["https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112555.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/24-112578.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112537.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112538.webp"]'::jsonb, E'2021-02-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/24165', E'ja', 42, E'伊王島町', E'伊王島町（いおうじまちょう）は、長崎港外、長崎市（旧西彼杵郡）香焼町沖にある伊王島・沖之島を含んでいた町。自治体人口に占めるカトリック教徒の比率が日本で最も高かった。\n\n2005年（平成17年）1月4日に長崎市に編入され、自治体としては消滅した。本項では現在の長崎市の一地区としての伊王島（いおうじま）についても記述する。\n\n伊王島地区（長崎市役所伊王島地域センター管内）の人口は691人（2018年2月末日現在、住民基本台帳）。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225036.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225037.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225038.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225039.webp"]'::jsonb, E'2025-02-19'::timestamptz, E'伊王島町', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E4%BC%8A%E7%8E%8B%E5%B3%B6%E7%94%BA'),
(E'https://matcha-jp.com/jp/23496', E'ja', 42, E'【2026】長崎ランタンフェスティバル開催日程はいつ？見どころや楽しみ方を徹底解説', E'この記事では、長崎ランタンフェスティバルに行きたい人に向けて、長崎ランタンフェスティバルの見どころや楽しみ方、2026年の日程を解説します。アクセスや駐車場情報についても解説しているので、ぜひ参考にしてみてください！\n\n2026年は2月6日から2月23日までで、約15,000個のランタンや華やかなオブジェなど、さまざまな展示を楽しめます。また、展示だけでなく、中国の歴史を感じる「皇帝パレード」や龍踊りや二胡演奏などの「ステージイベント」など、魅力盛りだくさんなイベントになっています。\n\nこの記事では、2026長崎ランタンフェスティバルの見どころや楽しみ方、アクセス、駐車場情報などを解説するので、ぜひ最後までご覧ください！\n\nここからは、2026長崎ランタンフェスティバルの見どころを厳選してご紹介します。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217860.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217859.webp","https://resources.matcha-jp.com/resize/720x2000/2025/11/04-248829.webp","https://resources.matcha-jp.com/resize/720x2000/2025/11/04-248830.webp"]'::jsonb, E'2025-01-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/9813', E'ja', 42, E'平和公園', E'長崎市平和公園（ながさきし へいわこうえん）は、日本の長崎県長崎市にある公園である。1945年（昭和20年）8月9日に投下された原子爆弾落下中心地（爆心地）と、その北側の丘の上とを含めた地域に平和を祈って設けられた。\n\n3つ（5つ）のゾーンから構成されている。毎年8月9日の長崎原爆の日（長崎原爆忌）には、平和祈念像前の式典広場にて長崎原爆犠牲者慰霊平和祈念式典が開催される。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103123.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103124.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103125.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103127.webp"]'::jsonb, E'2020-05-29'::timestamptz, E'平和公園', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%B9%B3%E5%92%8C%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/jp/20814', E'ja', 43, E'上通', E'上通（かみとおり）は、熊本県熊本市中央区の目抜き通りである通町筋の市電停留所付近から見て北へ伸びるアーケードと並木坂で構成される通りである。\n\nまた、広義では一帯の繁華街を上通と呼称することもある。町名は「上通町」、商店街の名前では「上通」だが、一般には「上通り」とも書き、店舗名などでも用いられる。\n\nアーケードを横切る桜井通り、並行するオークス通り、上乃裏通りなどがある。通町筋を挟んで南側に伸びる下通が市役所・デパート・オフィス街に近く、裏手にも大小の店舗が多く民家が少ないのと異なり、上通の裏手には民家が混在していることも特徴である。\n\n都心部のファッションストリートであり、多くの若者でにぎわっている。近辺には熊本信愛女学院中学校・高等学校・熊本中央高等学校・熊本市立必由館高等学校などがあり、夕方になると下校途中で道草する高校生の姿も多い。日本で初めて広範囲にEdyを導入した電子マネー商店街でもある。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/31-190556.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194731.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194735.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194729.webp"]'::jsonb, E'2024-07-31'::timestamptz, E'上通', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E4%B8%8A%E9%80%9A'),
(E'https://matcha-jp.com/jp/24035', E'ja', 43, E'熊本城', E'熊本城（くまもとじょう）は、熊本県熊本市中央区（肥後国飽田郡熊本）にあった安土桃山時代から江戸時代の日本の城。別名「銀杏城（ぎんなんじょう）」。\n\n加藤清正が中世城郭を取り込み改築した平山城で、加藤氏改易後は幕末まで熊本藩細川家の居城だった。明治時代には西南戦争の戦場となった。\n\n西南戦争の直前に大小天守や御殿など本丸の建築群が焼失したが 宇土櫓を始めとする櫓・城門・塀が現存し、13棟（櫓11棟、門1棟、塀1棟）が国の重要文化財に指定されている。\n\nまた、城跡は「熊本城跡」として国の特別史跡に指定されている。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223814.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223815.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/28-226300.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223801.webp"]'::jsonb, E'2025-02-11'::timestamptz, E'熊本城', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E7%86%8A%E6%9C%AC%E5%9F%8E'),
(E'https://matcha-jp.com/jp/24026', E'ja', 43, E'阿蘇山', E'阿蘇山（あそさん、あそざん）は、日本の九州中央部、熊本県阿蘇地方に位置する火山。カルデラを伴う大型の複成火山であり、活火山である。\n\n阿蘇火山は、カルデラと中央火口丘で構成され、高岳、中岳、根子岳、烏帽子岳、杵島岳が阿蘇五岳と呼ばれている。最高点は高岳の標高1,592メートル。\n\nカルデラは南北25キロメートル、東西18キロメートルに及び（屈斜路湖に次いで日本では第2位）面積380平方キロメートルと広大である。\n\n阿蘇くじゅう国立公園に含まれる。2007年、日本の地質百選に「阿蘇」として選定。2009年10月には、カルデラ内外の地域で、巨大噴火の歴史と生きた火口を体感できる「阿蘇ジオパーク」として日本ジオパーク、世界ジオパークに認定された。「日本百名山」の一座としても取り上げられている。、', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225347.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225348.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225349.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225350.webp"]'::jsonb, E'2025-02-10'::timestamptz, E'阿蘇山', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E9%98%BF%E8%98%87%E5%B1%B1'),
(E'https://matcha-jp.com/jp/10212', E'ja', 44, E'別府温泉', E'別府温泉（べっぷおんせん）は、大分県別府市内各地に数百ある温泉の総称。広義には別府温泉郷ともいい、特に古くから由来の異なる8つの温泉地は別府八湯と呼ばれている。\n\n狭義には別府八湯を構成する温泉地のうちの別府市中心部にある温泉街をいう（「#別府温泉」参照）。温泉都市として知られる別府は、源泉数、湧出量ともに日本一。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108692.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110690.webp"]'::jsonb, E'2020-12-06'::timestamptz, E'別府温泉', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E5%88%A5%E5%BA%9C%E6%B8%A9%E6%B3%89'),
(E'https://matcha-jp.com/jp/24986', E'ja', 44, E'湯布院町', E'湯布院町（ゆふいんちょう）は、大分県のほぼ中央に位置し、大分郡に属していた町である。町内に3箇所の温泉地がある。2005年10月1日に郡内の挾間町、庄内町と合併し、由布市（ゆふし）となり自治体としては消滅した。\n\n現在「湯布院町」という地名は、旧町域にある大字の頭に付く形で残っている。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/10-236024.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/10-236023.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/24-234460.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/24-234445.webp"]'::jsonb, E'2025-05-24'::timestamptz, E'湯布院町', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E6%B9%AF%E5%B8%83%E9%99%A2%E7%94%BA'),
(E'https://matcha-jp.com/jp/23754', E'ja', 44, E'湯布院町', E'湯布院町（ゆふいんちょう）は、大分県のほぼ中央に位置し、大分郡に属していた町である。町内に3箇所の温泉地がある。2005年10月1日に郡内の挾間町、庄内町と合併し、由布市（ゆふし）となり自治体としては消滅した。\n\n現在「湯布院町」という地名は、旧町域にある大字の頭に付く形で残っている。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220671.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220658.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220659.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220660.webp"]'::jsonb, E'2025-01-23'::timestamptz, E'湯布院町', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E6%B9%AF%E5%B8%83%E9%99%A2%E7%94%BA'),
(E'https://matcha-jp.com/jp/23349', E'ja', 45, E'地鶏が楽しめる日本全国の名店8選！種類や若鶏との違いも解説', E'日本でグルメを楽しむなら、濃厚な旨味が特徴の地鶏を使った料理がおすすめです。本記事では、地鶏の基礎知識と種類、地鶏料理を味わえる全国の人気店舗を紹介します。品種ごとの風味を持つ地鶏は、焼き鳥や鍋、グリルなどさまざまな料理で楽しめます。\n\n日本の代表的なグルメは数多くあります。その中でも、最近注目を集めているのが「地鶏」です。この記事では、各土地の名産品にもなっている地鶏の種類、一般的な鶏との違い、地鶏ならではの旨味を存分に味わえるおすすめの店舗を紹介します。\n\nなお、在来種とは、明治時代までに国内で成立または導入され定着した38種類の鶏を指します。高級食材として扱われる地鶏は、旨味とコク、弾力のある歯ごたえが特徴です。\n\n日本3大地鶏として知られているのが、秋田県の「比内(ひない)地鶏」、愛知県の「名古屋コーチン」、鹿児島県の「薩摩地鶏」です。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216252.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216253.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/20-216357.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/20-216358.webp"]'::jsonb, E'2024-12-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/7355', E'ja', 45, E'写真映えスポットがいっぱい！九州・宮崎の絶対行きたい10スポット＆絶品8グルメ', E'九州南部にある宮崎県は、暖かい気候と美しい海や自然に恵まれた地域です。高千穂峡や青島神社などインスタ映えするスポット、さらにマンゴーや宮崎牛といったご当地グルメがたくさん！ 宮崎県でぜひ訪れたいスポット、楽しみたいグルメを一挙ご紹介します。\n\n宮崎県へは飛行機でのアクセスが便利！ 国際線では台湾からの直行便があり、国内も羽田空港をはじめとする日本各地からの便があります。\n\n宮崎空港は宮崎市の中心部近くに位置しています。九州の中には県をまたいでバスや鉄道も走っており、博多(福岡県)からは高速バスで約4時間半(4,630円)です。\n\n宮崎県内には電車やバスもありますが、県内は広いため、多く移動する場合は車を使うのが便利。空港でレンタカーを借りて回るのがオススメです。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75848.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75843.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75844.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75845.webp"]'::jsonb, E'2019-04-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/2030', E'ja', 45, E'イースター島公認のモアイ像も!!日本の元祖"リゾート地"、宮崎県の定番スポット＆グルメ5選', E'日本にイースター島公認のモアイ像があるのを知っていますか？九州の宮崎県には、モアイ像だけではない魅力が詰まっています。今回は、洞窟にある鵜戸神宮やB級グルメ冷や汁など共に宮崎県の魅力を紹介します。\n\n宮崎県は九州地方の東南部に位置する県。温暖な気候で、南国のような情緒を感じられる土地です。\n\n日本のリゾート地の元祖とも言える県で、1960年代には新婚旅行の行き先としてとても人気になりました。現在は温かな気候を活かし、日本のプロ野球チームがスプリングキャンプを行う土地としても有名です。\n\n世界的にも評価の高い「宮崎牛」や「宮﨑地鶏」に代表される食肉産業、高級マンゴー「太陽の卵」などの果実栽培が主な産業です。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/20-126854.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/20-126849.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/20-126850.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/20-126851.webp"]'::jsonb, E'2018-04-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/3981', E'ja', 46, E'甑島列島', E'甑島列島（こしきしまれっとう）は、東シナ海にある列島。鹿児島県薩摩川内市に属する。甑列島（こしきれっとう）ともいう。上甑島（かみこしきしま）、中甑島（なかこしきしま）、下甑島（しもこしきしま）の順で北東から南西に連なる有人島3島と多数の小規模な無人島からなる。\n\n上甑島南西にある「甑」（蒸籠）の形をした大岩を甑大明神として崇拝したことに由来し、かつては「古敷島」「小敷島」「子敷島」「古志岐島」などとも書いた。\n\n3 kmである。従来、「こしきじま」という呼称であったが、薩摩川内市は国土地理院に変更を申請し、2014年8月に「こしきしま」に呼称が変更された（#名称参照）。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/22-19383.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17461.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17977.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17464.webp"]'::jsonb, E'2017-04-10'::timestamptz, E'甑島列島', E'Wikipedia (CC BY-SA 4.0)', E'https://ja.wikipedia.org/wiki/%E7%94%91%E5%B3%B6%E5%88%97%E5%B3%B6'),
(E'https://matcha-jp.com/jp/24865', E'ja', 46, E'鹿児島県のローカルを楽しむ！ 地元で愛される観光＆ショッピングスポット6選', E'鹿児島県に多くの有名観光地がありますが、温泉地や商店街のほか、お得に買い物ができる「スポーツデポ フレスポジャングルパーク店」や「GOLF5 鹿児島与次郎店」など地元民に愛される場所も見逃せません。本記事ではそんなローカルスポットを紹介します。\n\n鹿児島のランドマーク 桜島 Photo by PIXTA 九州の鹿児島県といえば、多くの人がまず雄大な桜島を思い浮かべるでしょう。しかし、鹿児島県の魅力はそれだけではありません。\n\n鹿児島県には豊かな自然、独特の文化と歴史、そして多彩な郷土料理があり、国内外から訪れる多くの観光客を魅了しています。\n\n温泉、ショッピング、アウトドアなど、楽しみ方もさまざま。今回は、地元の人たちにも人気の観光スポットを厳選して6つ紹介します。驚きと感動に満ちた旅をしてみましょう。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232922.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232888.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233503.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233504.webp"]'::jsonb, E'2025-05-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/jp/23348', E'ja', 46, E'黒豚が楽しめる日本全国の名店8選！おすすめ料理も紹介', E'黒豚を使った代表的な料理や、黒豚を味わえるおすすめのお店を紹介した記事です。黒豚料理を提供しているお店は、名産地の鹿児島県だけでなく、東京や大阪にもあります。黒豚のしゃぶしゃぶやすき焼きなどを食べて、日本のブランド豚・黒豚の美味しさを堪能してください。\n\n日本にはさまざまなご当地グルメがありますが、おすすめの食べ物のひとつが「黒豚」です。\n\n黒豚とは日本のブランド豚で、やわらかく旨味がたっぷりなことから人気を集めています。この記事では、黒豚を使った代表的な料理と、黒豚を堪能できるおすすめのお店を鹿児島・東京・大阪エリアからピックアップして紹介します。\n\n黒豚とは、豚の品種のひとつである「バークシャー種」のことです。バークシャー種は明治時代に日本に入り、鼻先と手足、しっぽの先以外が黒いため、黒豚と呼ばれるようになりました。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216235.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216237.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216239.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216240.webp"]'::jsonb, E'2024-12-19'::timestamptz, null, null, null)
